  async setContinueStoryAfterCalls({ scope: inputScope, playerInstanceId, enabled }) { const scope = requireEventScope(inputScope); const current = await this.get({ scope, playerInstanceId }); return this.#unitOfWork.readwrite({ stores: ['phoneUiPreferences'], scope }, async repositories => { const row = Object.freeze({ ...current, continueStoryAfterCalls: Boolean(enabled), updatedAt: new Date().toISOString() }); await repositories.phoneUiPreferences.put(row); return row; }); }
